static void reveal(QWidget *widget) {
 require(widget,"Function navigation control absent");
 for(auto *page=widget;page;page=page->parentWidget()) {
  for(auto *tabs:widget->window()->findChildren<QTabWidget*>())if(tabs->indexOf(page)>=0)tabs->setCurrentWidget(page);
  if(auto *scroll=qobject_cast<QScrollArea*>(page))scroll->ensureWidgetVisible(widget);
 }
 events();require(widget->isVisible()&&widget->isEnabled(),"Function navigation control unreachable");acceptanceView(*widget);
}

static QJsonArray csv(const QByteArray &bytes) {
 QJsonArray rows;
 for(const auto &line:QString::fromUtf8(bytes).trimmed().split('\n')) {
  QJsonArray row;for(const auto &word:line.split(',')){bool ok=false;double value=word.trimmed().toDouble(&ok);require(ok&&std::isfinite(value),"Function navigation CSV contains nonnumeric data");row.append(value);}rows.append(row);
 }
 return rows;
}

